type K5L10n = Record<K5Lang, string>;

interface K5PracticeConfig {
  topic: K5L10n;
  focus: K5L10n;
  hint1: K5L10n;
  hint2: K5L10n;
  quiz: string;
  icon: string;
  color: string;
  emoji: string;
}

